from decimal import Decimal
from typing import Any


def _value(record: dict, column: str) -> Any:
    return record.get(column, "")


def _number(value: Any) -> Decimal:
    if value == "":
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    if tables is None:
        return ""

    for row in tables.get(table_name, ()):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            return row.get(output_column, "")

    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []
    old_record = {} if event == "INSERT" or old is None else old

    # ORD-001
    if table == "ORD_HEADER" and event in ("INSERT", "UPDATE"):
        discount = _number(_value(record, "DISC_PCT"))
        if not (discount >= Decimal("0") and discount <= Decimal("100")):
            errors.append(
                {
                    "code": "E5001",
                    "message": "Discount out of range",
                    "severity": "BLOCK",
                }
            )

    # ORD-002
    if table == "ORD_HEADER" and event == "UPDATE":
        discount = _number(_value(record, "DISC_PCT"))
        owner_role = _lookup(
            tables,
            "USR_MASTER",
            "USR_ID",
            _value(record, "OWNER_UID"),
            "ROLE_ID",
        )
        if not (
            not (
                discount > Decimal("20")
                and owner_role != "MGR"
                and owner_role != "ADMIN"
            )
        ):
            errors.append(
                {
                    "code": "E5002",
                    "message": "Discount over 20 percent requires manager role",
                    "severity": "BLOCK",
                }
            )

    # ORD-003
    if table == "ORD_HEADER" and event == "UPDATE":
        old_status = _value(old_record, "STAT_CD")
        new_status = _value(record, "STAT_CD")
        if not (
            not (
                old_status == "I"
                and new_status != "I"
                and new_status != "X"
            )
        ):
            errors.append(
                {
                    "code": "E5003",
                    "message": "Invoiced order can only be cancelled",
                    "severity": "BLOCK",
                }
            )

    # ORD-004
    if table == "ORD_LINE" and event in ("INSERT", "UPDATE"):
        quantity = _number(_value(record, "QTY"))
        if not quantity > Decimal("0"):
            errors.append(
                {
                    "code": "E5004",
                    "message": "Quantity must be positive",
                    "severity": "BLOCK",
                }
            )

    # ORD-005
    if table == "ORD_LINE" and event == "INSERT":
        active_flag = _lookup(
            tables,
            "PROD_MASTER",
            "PROD_ID",
            _value(record, "PROD_ID"),
            "ACTIVE_FLG",
        )
        if active_flag != "Y":
            errors.append(
                {
                    "code": "E5005",
                    "message": "Product not active",
                    "severity": "BLOCK",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
